package com.tekwatt.admin.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.*;@Entity @Table(name="role_policies",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","role_name"}))public class RolePolicy{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,length=60)private String roleName;@Column(nullable=false,columnDefinition="TEXT")private String permissions;@Column(nullable=false)private boolean systemRole;@Column(nullable=false)private Instant updatedAt;protected RolePolicy(){}public RolePolicy(UUID t,String n){id=UUID.randomUUID();tenantId=t;roleName=n;permissions="";updatedAt=Instant.now();}public void update(Collection<String>p){permissions=String.join(",",new TreeSet<>(p));updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public String getRoleName(){return roleName;}public List<String>getPermissionList(){return permissions.isBlank()?List.of():List.of(permissions.split(","));}public boolean isSystemRole(){return systemRole;}public Instant getUpdatedAt(){return updatedAt;}}
